// === Tab: mySketch.js ===
/*
It is a 2D shader made for the weekly Creative Coding Challenge
(https://openprocessing.org/curation/78544) on the theme "Generative Landscapes".
*/

let theShader, dpr = Math.min(1, 0.5 * window.devicePixelRatio), ww = window.innerWidth*dpr, wh = window.innerHeight*dpr, startRandom;
const canvasStyle = 'width:100%;height:auto;touch-action:none;object-fit:contain;'

function windowResized() {
	ww = window.innerWidth*dpr; wh = window.innerHeight*dpr;
  resizeCanvas(ww, wh);
	const canvas = document.querySelector('canvas');
	canvas.style = canvasStyle;
}

function preload(){
	theShader = loadShader('https://openprocessing.org/sketch/2588006/files/vert.glsl', 'frag.glsl');
}

function setup() {
  pixelDensity(1);
  createCanvas(ww, wh, WEBGL);
	var canvas = document.querySelector('canvas');
	canvas.style = canvasStyle;
	startRandom = Math.random();
}

function draw() {
  shader(theShader);
  theShader.setUniform("resolution", [width, height]);
  theShader.setUniform("time", millis() / 1000.0);
  rect(0,0,width,height);
}

// Override to enable webgl2 and support for high resolution and retina displays
p5.RendererGL.prototype._initContext = function() {
	try { this.drawingContext = this.canvas.getContext('webgl2', this._pInst._glAttributes) ||
			this.canvas.getContext('experimental-webgl', this._pInst._glAttributes);
		if (this.drawingContext === null) { throw new Error('Error creating webgl context');
		} else { const gl = this.drawingContext;
			gl.viewport(0, 0, ww, wh);
			this._viewport = this.drawingContext.getParameter(this.drawingContext.VIEWPORT);
		} } catch (er) { throw er; }
};

// === Tab: vert.glsl ===
#version 300 es 
in vec3 aPosition; void main() { gl_Position=vec4(aPosition*2.-1., 1.0); }

// === Tab: frag.glsl ===
#version 300 es
/*********
* made by Matthias Hurrle (@atzedent)
* enhanced with additional visual effects
*/
precision highp float;
out vec4 O;
uniform vec2 resolution;
uniform float time;

#define FC gl_FragCoord.xy
#define R resolution
#define TT time
#define T (10.+S(.0,20.,floor(20.*fract(.005*TT))))
#define S smoothstep
#define N normalize
#define gyr(a) dot(sin(a),cos((a).yzx))

// Color palette function
vec3 palette(float t) {
    // More vibrant color palette
    vec3 a = vec3(0.5, 0.5, 0.5);
    vec3 b = vec3(0.5, 0.5, 0.5);
    vec3 c = vec3(1.0, 1.0, 1.0);
    vec3 d = vec3(0.3, 0.2, 0.2);

    return a + b * cos(6.28318 * (c * t + d));
}

float rnd(vec3 p) { 
    p = fract(p * vec3(12.9898, 78.233, 156.345)); 
    p += dot(p, p + 34.56); 
    return fract(p.x * p.y * p.z); 
}

// Improved FBM with more octaves and varied frequencies
float fbm(vec3 p) {
    p.x -= 2.4;
    float t = 0.0, a = 1.0;

    for (int i = 0; i < 8; i++) {
        p.xz += vec2(T * 12.1 / a, t * 0.5);
        // Add rotation to the domain
        float angle = 0.15 * TT * float(i);
        mat2 rot = mat2(cos(angle), -sin(angle), sin(angle), cos(angle));
        p.xz = rot * p.xz;

        a *= 0.5;
        t += gyr(p / (a + 1e-5)) * a;
    }

    return t;
}

// Enhanced height map with additional terrain features
float map(vec3 p) {
    // Base terrain
    float terrain = p.y + 0.8 - S(0.0, 1.75, cos(1.518 * fbm(0.1 + p * 0.2)));

    // Add mountain ridges
    float ridges = 0.2 * abs(fbm(p * 0.5 + vec3(0.0, 0.0, TT * 0.1)));

    // Add small details
    float details = 0.05 * fbm(p * 2.0 + vec3(TT * 0.2, 0.0, 0.0));

    return terrain - ridges - details;
}

// Environment fog function
vec3 applyFog(vec3 color, float distance, vec3 rayDir) {
    // Sky color with time variation
    vec3 skyColor = mix(
        vec3(0.5, 0.7, 0.9), 
        vec3(0.8, 0.3, 0.2), 
        S(0.0, 1.0, sin(TT * 0.1) * 0.5 + 0.5)
    );

    // Directional light influence
    vec3 sunDir = N(vec3(cos(TT * 0.1), 0.5, sin(TT * 0.1)));
    float sunInfluence = max(0.0, dot(rayDir, sunDir));

    // Sun halo
    vec3 sunColor = vec3(1.0, 0.6, 0.3) * pow(sunInfluence, 8.0);

    // Apply fog based on distance
    float fogAmount = 1.0 - exp(-distance * 0.15);

    return mix(color, skyColor + sunColor, fogAmount);
}

// Soft shadow calculation
float softshadow(vec3 ro, vec3 rd, float mint, float maxt, float k) {
    float res = 1.0;
    float t = mint;
    for (int i = 0; i < 12 && t < maxt; i++) {
        float h = map(ro + rd * t);
        if (h < 0.001) return 0.0;
        res = min(res, k * h / t);
        t += h;
    }
    return res;
}

// Ambient occlusion approximation
float ao(vec3 p, vec3 n) {
    float occ = 0.0;
    float weight = 1.0;
    for (float i = 0.0; i < 5.0; i++) {
        float len = 0.01 + 0.02 * i;
        float d = map(p + n * len);
        occ += (len - d) * weight;
        weight *= 0.85;
    }
    return 1.0 - clamp(occ, 0.0, 1.0);
}

void main(void) {
    vec2 uv = (FC - 0.5 * R) / min(R.x, R.y);

    // Enhanced wave effect
    float wave = sin(2.0 * 3.141592 * TT - 2.0 + rnd(floor(uv.yyy * 9.0)) * 0.5);
    uv.y *= tanh(wave * 3.0 + 3.0);

    // Add subtle lens distortion
    float distortion = 0.1;
    float r2 = uv.x * uv.x + uv.y * uv.y;
    uv *= 1.0 + distortion * r2;

    // Setup ray
    vec3 col = vec3(0.0);
    vec3 p = vec3(0.0, 0.0, mod(TT, 10.0));
    vec3 rd = N(vec3(uv, 1.0));

    // Add camera shake/movement
    float camShake = 0.03 * sin(TT * 3.0);
    p.x += camShake * sin(TT * 5.0);
    p.y += camShake * sin(TT * 4.0);

    // Ray march
    float totalDistance = 0.0;
    bool hit = false;

    for (float i = 0.0; i < 100.0; i++) {
        float d = map(p) * mix(0.8, 1.0, rnd(p));

        totalDistance += d;

        if (d < 1e-2) {
            hit = true;

            // Calculate normal for lighting
            vec2 e = vec2(0.01, 0.0);
            vec3 normal = N(vec3(
                map(p + e.xyy) - map(p - e.xyy),
                map(p + e.yxy) - map(p - e.yxy),
                map(p + e.yyx) - map(p - e.yyx)
            ));

            // Basic lighting
            vec3 lightDir = N(vec3(0.5, 0.8, 0.3));
            float diff = max(dot(normal, lightDir), 0.0);

            // Shadow and ambient occlusion
            float shadow = softshadow(p, lightDir, 0.1, 3.0, 16.0);
            float ambOcc = ao(p, normal);

            // Surface color based on height and normal
            vec3 albedo = palette(0.3 + 0.4 * fbm(p * 0.4));

            // Final color with lighting
            col = albedo * (0.2 + 0.8 * diff * shadow) * ambOcc;

            // Add subtle specular highlight
            vec3 reflDir = reflect(rd, normal);
            float spec = pow(max(dot(reflDir, lightDir), 0.0), 32.0);
            col += vec3(1.0, 0.9, 0.7) * spec * shadow;

            break;
        }

        if (d > 2.0 || totalDistance > 20.0) {
            // Sky color for rays that don't hit
            float t = uv.y * 0.5 + 0.5;
            col = mix(
                vec3(0.8, 0.3, 0.2), 
                vec3(0.2, 0.3, 0.8), 
                t
            );

            // Add stars
            vec3 stars = vec3(pow(rnd(vec3(uv * 500.0, TT * 0.01)), 24.0));
            col += stars;

            break;
        }

        p += rd * d;
    }

    // Apply fog/atmosphere
    if (hit) {
        col = applyFog(col, totalDistance, rd);
    }

    // Tone mapping and gamma correction
    col = col / (col + vec3(1.0)); // Reinhard tone mapping
    col = pow(col, vec3(0.4545)); // Gamma correction

    // Add subtle vignette
    float vignette = 1.0 - r2 * 0.5;
    col *= vignette;

    // Final output
    O = vec4(max(col, 0.0), 1.0);
}

